    class PriorityQueue {
    constructor() {
        this.queue = [];
    }

    enqueue(element) {
        this.queue.push(element);
        this.queue.sort((a, b) => a[0] - b[0]);
    }

    dequeue() {
        if (this.isEmpty()) return "Queue is empty";
        return this.queue.shift();
    }

    isEmpty() {
        return this.queue.length === 0;
    }
}

